package main

import "fmt"

const MOD = 1000000007
const K = 1010

var dp [K][K]int64

func powmod(a, x int64) int64 {
	res := int64(1)
	a %= MOD
	for x > 0 {
		if x&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		x >>= 1
	}
	return res
}

func main() {
	var k, va, vb int
	fmt.Scan(&k, &va, &vb)

	den := powmod(int64(va+vb), MOD-2)
	pa := int64(va) * den % MOD
	pb := int64(vb) * den % MOD
	one_b := pa * powmod(pb, MOD-2) % MOD

	for i := k - 1; i >= 0; i-- {
		for j := k; j >= 1; j-- {
			if i+j >= k {
				dp[i][j] = (int64(i+j) + one_b) % MOD
			} else {
				dp[i][j] = (pa*dp[i][j+1] + pb*dp[i+j][j]) % MOD
			}
		}
	}
	fmt.Println(dp[0][1])
}

